"""Compose frozen parent SQL without editing it. No DB/network access."""
from pathlib import Path
import json,hashlib,re
R=Path(__file__).resolve().parents[1];REPO=R.parents[1]
foundation=next((R.parent/'school06/supabase/migrations').glob('*foundation.sql'));core=next((R.parent/'school06/supabase/migrations').glob('*core.sql'));stock=next((R.parent/'school07/supabase/migrations').glob('*.sql'))
names=json.loads((R.parent/'school06/sql/public-rpc-names.json').read_text())+list(json.loads((R.parent/'school07/sql/rpc-contracts.json').read_text()));assert len(set(names))==54
array='ARRAY['+','.join("'"+n+"'"for n in names)+']::text[]'
fp=(R.parent/'school06/sql/fingerprint-expression.sql').read_text().strip().rstrip(';');fp=re.sub(r"p.proname=ANY\(ARRAY\[.*?\]::text\[\]\)", 'p.proname=ANY('+array+')',fp,count=1,flags=re.S)
# No fixture/Auth grant is included. Original local S07 guard remains intentionally local-only.
def inner(p):
 s=p.read_text();s,n=re.subn(r'\bBEGIN;', '',s,count=1);assert n==1;s,n=re.subn(r'COMMIT;\s*$', '',s,count=1);assert n==1;return s
payload='-- Frozen SCHOOL06 core\n'+inner(core)+'\n-- Frozen SCHOOL07 extension\n'+inner(stock)
digest=hashlib.sha256((foundation.read_text()+payload+fp+Path(__file__).read_text()).encode()).hexdigest()
guard="IF current_user<>session_user OR current_database()<>'school01a'OR current_setting('bogunon.ws_install_mode',true)IS DISTINCT FROM 'isolated'THEN RAISE EXCEPTION 's08_isolated_direct_session_required';END IF;"
sql="BEGIN;SET LOCAL lock_timeout='5s';SELECT pg_advisory_xact_lock(hashtextextended('bogunon:school06:install',0));DO $s08$ DECLARE f record;target text;impl oid;BEGIN "+guard
sql+="IF to_regclass('workspace_private.s08_release')IS NOT NULL THEN EXECUTE $auth_recheck$"+(R.parent/'school06/sql/auth-capability-check.sql').read_text()+"$auth_recheck$;IF NOT EXISTS(SELECT 1 FROM workspace_private.s08_release WHERE digest='"+digest+"'AND state IN('closed','active')AND fingerprint="+fp+")THEN RAISE EXCEPTION 's08_release_or_catalog_drift';END IF;RETURN;END IF;"
sql+="IF to_regclass('workspace_private.s06_install_manifest')IS NULL THEN RAISE EXCEPTION 'foundation_required';END IF;IF EXISTS(SELECT 1 FROM workspace_private.s06_install_manifest WHERE phase='core')THEN RAISE EXCEPTION 'existing_workspace_requires_separate_review';END IF;"
sql+="EXECUTE $cumulative_payload$"+payload+"$cumulative_payload$;"
sql+="CREATE TABLE workspace_private.s08_release(digest text PRIMARY KEY,state text NOT NULL,fingerprint text NOT NULL,closed_fingerprint text NOT NULL);CREATE TABLE workspace_private.s08_rpc_manifest(public_signature text PRIMARY KEY,private_signature text NOT NULL);"
sql+="ALTER TABLE workspace_private.s08_release OWNER TO ws_owner;ALTER TABLE workspace_private.s08_rpc_manifest OWNER TO ws_owner;"
sql+="ALTER TABLE workspace_private.s08_release ENABLE ROW LEVEL SECURITY;ALTER TABLE workspace_private.s08_release FORCE ROW LEVEL SECURITY;ALTER TABLE workspace_private.s08_rpc_manifest ENABLE ROW LEVEL SECURITY;ALTER TABLE workspace_private.s08_rpc_manifest FORCE ROW LEVEL SECURITY;REVOKE ALL ON workspace_private.s08_release,workspace_private.s08_rpc_manifest FROM PUBLIC,anon,authenticated,ws_runtime,ws_authz_reader;"
sql+="EXECUTE format('GRANT SELECT,INSERT,UPDATE ON workspace_private.s08_release,workspace_private.s08_rpc_manifest TO %I',current_user);EXECUTE format('CREATE POLICY s08_installer ON workspace_private.s08_release TO %I USING(true)WITH CHECK(true)',current_user);EXECUTE format('CREATE POLICY s08_installer ON workspace_private.s08_rpc_manifest TO %I USING(true)WITH CHECK(true)',current_user);"
sql+="FOR f IN SELECT p.oid::regprocedure sig,p.prosrc FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'AND p.proname=ANY("+array+")LOOP target:=(regexp_match(f.prosrc,'workspace_private[.]([a-zA-Z0-9_]+)'))[1];SELECT p.oid INTO impl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='workspace_private'AND p.proname=target;IF impl IS NULL THEN RAISE EXCEPTION 'rpc_chain_unresolved';END IF;INSERT INTO workspace_private.s08_rpc_manifest VALUES(f.sig,impl::regprocedure::text);END LOOP;IF(SELECT count(*)FROM workspace_private.s08_rpc_manifest)<>54 THEN RAISE EXCEPTION 'rpc_manifest_count';END IF;"
sql+="INSERT INTO workspace_private.s08_release VALUES('"+digest+"','closed',"+fp+","+fp+");END$s08$;COMMIT;\n"
next((R/'supabase/migrations').glob('*.sql')).write_text('-- LOCAL candidate cumulative application install; foundation/Auth prerequisite separate.\n'+sql)
(R/'sql/01-foundation.sql').write_bytes(foundation.read_bytes())
# Lifecycle operates on the explicit cumulative release, never reseeds frozen parent manifests.
auth=(R.parent/'school06/sql/auth-capability-check.sql').read_text()
activate="BEGIN;SET LOCAL lock_timeout='5s';SELECT pg_advisory_xact_lock(hashtextextended('bogunon:school06:install',0));"+auth+"DO $activate$ DECLARE r record;BEGIN "+guard+"IF NOT EXISTS(SELECT 1 FROM workspace_private.s08_release WHERE digest='"+digest+"'AND state IN('closed','active')AND fingerprint="+fp+")THEN RAISE EXCEPTION 's08_release_or_catalog_drift';END IF;FOR r IN SELECT *FROM workspace_private.s08_rpc_manifest LOOP EXECUTE format('GRANT EXECUTE ON FUNCTION %s,%s TO authenticated',r.public_signature,r.private_signature);END LOOP;UPDATE workspace_private.s08_release SET state='active',fingerprint="+fp+";END$activate$;COMMIT;\n"
close="BEGIN;SET LOCAL lock_timeout='5s';SELECT pg_advisory_xact_lock(hashtextextended('bogunon:school06:install',0));DO $close$ DECLARE r record;before_ok boolean;BEGIN "+guard+"SELECT fingerprint="+fp+"INTO before_ok FROM workspace_private.s08_release;FOR r IN SELECT *FROM workspace_private.s08_rpc_manifest LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s,%s FROM PUBLIC,anon,authenticated',r.public_signature,r.private_signature);END LOOP;UPDATE workspace_private.s08_release SET state=CASE WHEN before_ok AND closed_fingerprint="+fp+"THEN 'closed'ELSE 'closed_unverified'END,fingerprint=CASE WHEN before_ok AND closed_fingerprint="+fp+"THEN closed_fingerprint ELSE fingerprint END;END$close$;COMMIT;\n"
(R/'sql/activate-local.sql').write_text('-- QA ONLY, production remains disabled.\n'+activate);(R/'sql/close-local.sql').write_text('-- Data-preserving closure of all54 endpoints.\n'+close)
(R/'sql/fingerprint.sql').write_text(fp+';\n')
(R/'reference/sql-provenance.json').write_text(json.dumps({'sources':[{'path':p.relative_to(REPO).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}for p in [foundation,core,stock]],'transform':'strip only outer BEGIN/COMMIT; preserve nested role/authz/closed gates; atomically compose core+inventory; new cumulative lifecycle ledger','release_spec_sha256':digest,'public_rpc_count':54,'public_rpc_names':names,'hosted':'NOT RUN; local-only S07 guard retained'},indent=2))
print('Cumulative core+stock generated;54 RPCs default CLOSED; frozen originals unchanged')

(R/'sql/install-candidate.sql').write_text("\\set ON_ERROR_STOP on\nSET bogunon.ws_install_mode='isolated';\nDO $$BEGIN IF current_database()<>'school01a'OR current_user<>session_user THEN RAISE EXCEPTION 's08_local_direct_only';END IF;END$$;\nSELECT to_regclass('workspace_private.s08_release')IS NOT NULL AS s08_present \\gset\n\\if :s08_present\n\\ir ../supabase/migrations/"+next((R/'supabase/migrations').glob('*.sql')).name+"\n\\else\n\\ir 01-foundation.sql\n\\ir ../supabase/migrations/"+next((R/'supabase/migrations').glob('*.sql')).name+"\n\\endif\n")
